[CmdletBinding()]param([string]$CheckerPath='tools/check-automation-evaluation-boundary.ps1')
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
$repoRoot=(& git rev-parse --show-toplevel 2>$null).Trim();if($LASTEXITCODE-ne 0-or[string]::IsNullOrWhiteSpace($repoRoot)){throw'Run inside the repository.'}
function Resolve-Repo([string]$p){if([IO.Path]::IsPathRooted($p)){[IO.Path]::GetFullPath($p)}else{[IO.Path]::GetFullPath((Join-Path $repoRoot $p))}}
$checker=Resolve-Repo $CheckerPath
$inputs=@('contracts/automation/evaluation-boundary.json','docs/adr/ADR-011-automation-and-evaluation.md','docs/threat-model/automation-and-evaluation.md','docs/prd-traceability.md','docs/product-spec.md','docs/implementation-plan.md','contracts/governance/capabilities.json','contracts/model/provider-boundary.json','contracts/domain/policy-state-boundary.json','contracts/reminder/adapter-boundary.json','contracts/support/support-matrix.json','contracts/build-skeleton/skeleton.json')
$script:count=0;$script:fail=[Collections.Generic.List[string]]::new()
function New-Root{$root=Join-Path ([IO.Path]::GetTempPath()) ('openloops-automation-'+[guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($root)|Out-Null;foreach($rel in $inputs){$target=Join-Path $root $rel;[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($target))|Out-Null;Copy-Item -LiteralPath (Join-Path $repoRoot $rel) -Destination $target};$root}
function Check([string]$root){$a=@('-NoProfile','-File',$checker,'-ManifestPath',(Join-Path $root 'contracts/automation/evaluation-boundary.json'),'-AdrPath',(Join-Path $root 'docs/adr/ADR-011-automation-and-evaluation.md'),'-ThreatPath',(Join-Path $root 'docs/threat-model/automation-and-evaluation.md'),'-TraceabilityPath',(Join-Path $root 'docs/prd-traceability.md'),'-ProductSpecPath',(Join-Path $root 'docs/product-spec.md'),'-ImplementationPlanPath',(Join-Path $root 'docs/implementation-plan.md'),'-GovernancePath',(Join-Path $root 'contracts/governance/capabilities.json'),'-ModelPath',(Join-Path $root 'contracts/model/provider-boundary.json'),'-PolicyPath',(Join-Path $root 'contracts/domain/policy-state-boundary.json'),'-ReminderPath',(Join-Path $root 'contracts/reminder/adapter-boundary.json'),'-SupportPath',(Join-Path $root 'contracts/support/support-matrix.json'),'-BuildPath',(Join-Path $root 'contracts/build-skeleton/skeleton.json'),'-Quiet');$o=@(& pwsh @a 2>&1|ForEach-Object{[string]$_});[pscustomobject]@{Code=$LASTEXITCODE;Output=($o-join"`n")}}
function JsonCase([string]$name,[string]$id,[string]$rel,[scriptblock]$mutate){$script:count++;$root=New-Root;try{$path=Join-Path $root $rel;$v=Get-Content -Raw -LiteralPath $path|ConvertFrom-Json -Depth 100;&$mutate $v;$v|ConvertTo-Json -Depth 100|Set-Content -LiteralPath $path -Encoding utf8NoBOM;$r=Check $root;if($r.Code-eq 0-or$r.Output-notmatch[regex]::Escape($id)){$script:fail.Add("$name (expected $id; exit $($r.Code))")}}finally{Remove-Item -LiteralPath $root -Recurse -Force -ErrorAction SilentlyContinue}}
function TextCase([string]$name,[string]$id,[string]$rel,[scriptblock]$mutate){$script:count++;$root=New-Root;try{$path=Join-Path $root $rel;$changed=&$mutate (Get-Content -Raw -LiteralPath $path);Set-Content -LiteralPath $path -Value $changed -Encoding utf8NoBOM;$r=Check $root;if($r.Code-eq 0-or$r.Output-notmatch[regex]::Escape($id)){$script:fail.Add("$name (expected $id; exit $($r.Code))")}}finally{Remove-Item -LiteralPath $root -Recurse -Force -ErrorAction SilentlyContinue}}
$base=& pwsh -NoProfile -File $checker 2>&1;if($LASTEXITCODE-ne 0){throw('Baseline automation checker failed: '+(@($base)-join"`n"))}

JsonCase 'hybrid flag default enabled' 'P0-AUTOMATION-FLAGS-001' 'contracts/automation/evaluation-boundary.json' {param($c)($c.flag_topology.flags|Where-Object{$_.id -eq 'hybrid_enabled'}).default=$true}
JsonCase 'automatic flag default enabled' 'P0-AUTOMATION-FLAGS-001' 'contracts/automation/evaluation-boundary.json' {param($c)($c.flag_topology.flags|Where-Object{$_.id -eq 'automatic_enabled'}).default=$true}
JsonCase 'flag flip without gate evidence' 'P0-AUTOMATION-FLAGS-001' 'contracts/automation/evaluation-boundary.json' {param($c)($c.flag_topology.flags|Where-Object{$_.id -eq 'hybrid_enabled'}).flip_requires=@('accountable owner release decision citing that gate evidence')}
JsonCase 'automatic flag flip without opt-in' 'P0-AUTOMATION-FLAGS-001' 'contracts/automation/evaluation-boundary.json' {param($c)($c.flag_topology.flags|Where-Object{$_.id -eq 'automatic_enabled'}).flip_requires=@('G-AUTO-FULL passed','accountable owner release decision citing that gate evidence')}
JsonCase 'flip path widened to settings preference' 'P0-AUTOMATION-FLAGS-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.flag_topology.prohibited_flip_paths=@($c.flag_topology.prohibited_flip_paths|Where-Object{$_ -ne 'settings preference alone'})}

JsonCase 'medium confidence auto-creates under hybrid' 'P0-AUTOMATION-MODES-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.mode_catalog.hybrid.create_eligibility='live narrow-category cases only: explicit promise, explicit directly addressed request, or explicit deterministic attribution, with a valid resolved deadline, medium or high calibrated confidence, deterministic identity, and no quote/delegation/coreference ambiguity'}
JsonCase 'ambiguous category becomes auto-eligible' 'P0-AUTOMATION-STRATA-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.catalogs.automatic_always_review_category_code=@($c.catalogs.automatic_always_review_category_code|Where-Object{$_ -ne 'ambiguous'})}
JsonCase 'undated case becomes auto-eligible' 'P0-AUTOMATION-STRATA-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.catalogs.automatic_always_review_category_code=@($c.catalogs.automatic_always_review_category_code|Where-Object{$_ -ne 'undated'})}
JsonCase 'identity-ambiguous case becomes auto-eligible' 'P0-AUTOMATION-STRATA-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.catalogs.automatic_always_review_category_code=@($c.catalogs.automatic_always_review_category_code|Where-Object{$_ -ne 'identity_ambiguous'})}
JsonCase 'hybrid category catalog admits an always-review category' 'P0-AUTOMATION-STRATA-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.catalogs.hybrid_create_category_code=@($c.catalogs.hybrid_create_category_code)+@('ambiguous')}

JsonCase 'historical batch auto-mutation permitted' 'P0-AUTOMATION-STRATA-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.mode_change_boundary.prohibited=@($c.mode_change_boundary.prohibited|Where-Object{$_ -ne 'retroactive historical batch creation or rewrite'})}
JsonCase 'mode change becomes retroactive' 'P0-AUTOMATION-STRATA-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.mode_change_boundary.prospective_only=$false}
JsonCase 'replay mutates a historical reminder' 'P0-AUTOMATION-ROLLBACK-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.rollback_boundary.prohibited=@($c.rollback_boundary.prohibited|Where-Object{$_ -ne 'historical batch mutation'})}

JsonCase 'corpus stored inside the repository' 'P0-AUTOMATION-CORPUS-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.corpus_governance.location='inside the repository alongside the public development fixtures'}
JsonCase 'corpus hash and version removed' 'P0-AUTOMATION-CORPUS-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.corpus_governance.immutability='corpus content may change after sealing; no hash or version is pinned'}
JsonCase 'tuning budget removed' 'P0-AUTOMATION-CORPUS-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.corpus_governance.tuning_budget='tuning may continue indefinitely against the same sealed corpus'}
JsonCase 'per-stratum threshold below 95 percent lower bound' 'P0-AUTOMATION-CORPUS-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.corpus_governance.confidence_rule='a passing point estimate alone is sufficient; no declared lower bound is required'}
JsonCase 'zero-mutation observation weakened into a guarantee' 'P0-AUTOMATION-CORPUS-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.corpus_governance.observation_framing='zero observed unintended mutations in at least 10,000 events proves the product will never mutate unintentionally'}
JsonCase 'sample-size declaration removed' 'P0-AUTOMATION-CORPUS-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.corpus_governance.sample_size_rule='left to the maker''s discretion at evaluation time'}
JsonCase 'family split rule removed' 'P0-AUTOMATION-CORPUS-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.corpus_governance.split_rule='split arbitrarily; a family may straddle a split'}
JsonCase 'contamination checks removed' 'P0-AUTOMATION-CORPUS-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.corpus_governance.contamination_checks='no contamination checks are required'}

JsonCase 'drift preserves calibration' 'P0-AUTOMATION-CALIBRATION-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.calibration_invalidation.effect='provider or model drift does not affect an already-flipped flag; calibration remains valid'}
JsonCase 'drift trigger catalog narrowed' 'P0-AUTOMATION-CALIBRATION-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.catalogs.calibration_drift_trigger_code=@($c.catalogs.calibration_drift_trigger_code|Where-Object{$_ -ne 'model_digest_or_label_change'})}
JsonCase 'post-drift automatic mutation permitted' 'P0-AUTOMATION-CALIBRATION-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.calibration_invalidation.post_drift_action='the pending automatic mutation still completes before any replay'}

JsonCase 'rollback becomes conditional' 'P0-AUTOMATION-ROLLBACK-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.rollback_boundary.properties=@($c.rollback_boundary.properties|Where-Object{$_ -ne 'unilateral'})}
JsonCase 'rollback requires owner approval' 'P0-AUTOMATION-ROLLBACK-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.rollback_boundary.prohibited=@($c.rollback_boundary.prohibited|Where-Object{$_ -ne 'required additional confirmation or owner approval to take effect'})}

JsonCase 'evaluation content persisted' 'P0-AUTOMATION-PRIVACY-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.evaluation_privacy_boundary.prohibited_values=@()}
JsonCase 'evaluation results imply profiling' 'P0-AUTOMATION-PRIVACY-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.evaluation_privacy_boundary.profiling_claim='permitted for personalized calibration'}
JsonCase 'reported metric catalog widened beyond section 8.2' 'P0-AUTOMATION-PRIVACY-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.catalogs.reported_metric_code=@($c.catalogs.reported_metric_code)+@('per_user_behavior_profile')}

JsonCase 'gate-passed claim' 'P0-AUTOMATION-CLAIMS-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.runtime_boundary.gates_passed=@('G-AUTO')}
JsonCase 'capability-enabled claim' 'P0-AUTOMATION-CLAIMS-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.claims.capabilities_enabled=@('hybrid_reminder_mode')}
JsonCase 'mode advertised claim' 'P0-AUTOMATION-CLAIMS-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.claims.modes_advertised=@('hybrid')}
JsonCase 'flag flipped claim' 'P0-AUTOMATION-CLAIMS-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.runtime_boundary.hybrid_enabled=$true}
JsonCase 'evaluation run claim' 'P0-AUTOMATION-CLAIMS-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.runtime_boundary.evaluation_run=$true}
JsonCase 'corpus created claim' 'P0-AUTOMATION-CLAIMS-001' 'contracts/automation/evaluation-boundary.json' {param($c)$c.runtime_boundary.corpus_created=$true}

JsonCase 'ADR-011 prematurely revert while capability claimed enabled' 'P0-AUTOMATION-CROSS-CONTRACT-001' 'contracts/governance/capabilities.json' {param($c)($c.adrs|Where-Object{$_.id -eq 'ADR-011'}).status='planned'}
JsonCase 'ADR-013 prematurely accepted' 'P0-AUTOMATION-CROSS-CONTRACT-001' 'contracts/governance/capabilities.json' {param($c)($c.adrs|Where-Object{$_.id -eq 'ADR-013'}).status='accepted'}
JsonCase 'hybrid capability enabled in governance' 'P0-AUTOMATION-CROSS-CONTRACT-001' 'contracts/governance/capabilities.json' {param($c)($c.capabilities|Where-Object{$_.id -eq 'hybrid_reminder_mode'}).state='enabled'}
JsonCase 'gate marked passed in governance' 'P0-AUTOMATION-CROSS-CONTRACT-001' 'contracts/governance/capabilities.json' {param($c)($c.gates|Where-Object{$_.id -eq 'G-AUTO'}).status='passed'}
JsonCase 'policy separate-decision drift' 'P0-AUTOMATION-CROSS-CONTRACT-001' 'contracts/domain/policy-state-boundary.json' {param($c)$c.separate_decisions.automation_modes_eligibility_evaluation_and_feature_flags='ADR-009'}
JsonCase 'reminder separate-decision drift' 'P0-AUTOMATION-CROSS-CONTRACT-001' 'contracts/reminder/adapter-boundary.json' {param($c)$c.separate_decisions.mode_semantics_eligibility_evaluation_flags_and_rollback='ADR-008'}
JsonCase 'support matrix claims a supported row' 'P0-AUTOMATION-CROSS-CONTRACT-001' 'contracts/support/support-matrix.json' {param($c)$c.claim_state.supported_rows=@('hybrid_reminder_mode')}
JsonCase 'build skeleton claims model provider runtime' 'P0-AUTOMATION-CROSS-CONTRACT-001' 'contracts/build-skeleton/skeleton.json' {param($c)$c.runtime_boundary.model_provider=$true}

TextCase 'spec contradiction appended' 'P0-AUTOMATION-INVENTORY-001' 'docs/product-spec.md' {param($t)$t+"`nContrary rule: hybrid mode auto-creates reminders for medium-confidence candidates.`n"}
TextCase 'plan contradiction appended' 'P0-AUTOMATION-INVENTORY-001' 'docs/implementation-plan.md' {param($t)$t+"`nP0-WI-14 enables hybrid mode and flips hybrid_enabled to true.`n"}
TextCase 'ADR contradiction appended' 'P0-AUTOMATION-CROSS-CONTRACT-001' 'docs/adr/ADR-011-automation-and-evaluation.md' {param($t)$t+"`nContrary decision: automatic mode may retroactively rewrite a historical batch once G-AUTO-FULL passes.`n"}
TextCase 'trace contradiction appended' 'P0-AUTOMATION-INVENTORY-001' 'docs/prd-traceability.md' {param($t)$t+"`nP0-WI-14 passed G-AUTO and G-AUTO-FULL and ships hybrid and automatic modes.`n"}
TextCase 'fresh checker preapproved' 'P0-AUTOMATION-FRESH-CHECKER-001' 'docs/prd-traceability.md' {param($t)$t-replace'\| P0-AUTOMATION-FRESH-CHECKER-001 \|([^\n]*)Passed at P0-WI-14 closure','| P0-AUTOMATION-FRESH-CHECKER-001 |$1Passed without independent review'}

if($script:fail.Count-gt 0){[Console]::Error.WriteLine(('FAIL: automation and evaluation synthetic mutations: '+($script:fail-join'; ')));exit 1};Write-Output ('PASS: automation and evaluation synthetic mutations ({0} rejection cases; OS temp only)' -f $script:count)
